fn reverse(a: &Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(a.len()); // Create a new vector with the same capacity as the input
    for i in (0..a.len()).rev() { // Iterate from the last index to the first
        result.push(a[i]); // Push the elements in reverse order
    }
    result // Return the reversed vector
}